CREATE TABLE learning_profiles(id TEXT PRIMARY KEY,logical_id TEXT NOT NULL REFERENCES ai_subjects(logical_id),source_version TEXT NOT NULL,profile_json TEXT NOT NULL CHECK(json_valid(profile_json)),created_at INTEGER NOT NULL,UNIQUE(logical_id,source_version));
CREATE TABLE learning_paths(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL REFERENCES learning_profiles(id),goal TEXT NOT NULL,experience TEXT NOT NULL,budget_minutes INTEGER NOT NULL CHECK(budget_minutes BETWEEN 5 AND 480),cache_key TEXT NOT NULL UNIQUE,path_json TEXT NOT NULL CHECK(json_valid(path_json)),created_at INTEGER NOT NULL);
CREATE TABLE learning_steps(path_id TEXT NOT NULL REFERENCES learning_paths(id),ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 4),name TEXT NOT NULL,completion_rule TEXT NOT NULL,PRIMARY KEY(path_id,ordinal));
CREATE TABLE practice_sessions(id TEXT PRIMARY KEY,path_id TEXT NOT NULL REFERENCES learning_paths(id),task_id TEXT NOT NULL,source_version TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('NOT_STARTED','READY','IN_PROGRESS','BLOCKED','SUBMITTED','VERIFIED','FAILED')),workspace TEXT NOT NULL,task_json TEXT NOT NULL CHECK(json_valid(task_json)),note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE verification_runs(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES practice_sessions(id),logical_id TEXT NOT NULL REFERENCES ai_subjects(logical_id),capability_version TEXT NOT NULL,environment_json TEXT NOT NULL CHECK(json_valid(environment_json)),task_id TEXT NOT NULL,test_method TEXT NOT NULL,started_at INTEGER NOT NULL,finished_at INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('NOT_TESTED','BLOCKED','RUNNING','PASSED','FAILED','INCONCLUSIVE','STALE')),failure_reason TEXT NOT NULL,layers_json TEXT NOT NULL CHECK(json_valid(layers_json)),input_hash TEXT,UNIQUE(session_id,test_method,input_hash));
CREATE TABLE verification_evidence(id TEXT PRIMARY KEY,verification_id TEXT NOT NULL REFERENCES verification_runs(id),evidence_type TEXT NOT NULL,evidence_location TEXT NOT NULL,evidence_hash TEXT NOT NULL,byte_count INTEGER NOT NULL,trust TEXT NOT NULL CHECK(trust IN('SELF_REPORTED','LOCAL_VALIDATOR','HUMAN_REVIEW')),UNIQUE(verification_id,evidence_hash));
CREATE TABLE learning_milestones(id TEXT PRIMARY KEY,logical_id TEXT NOT NULL REFERENCES ai_subjects(logical_id),source_version TEXT NOT NULL,stage TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('SELF_REPORTED','ARTIFACT_VERIFIED','NOT_VERIFIED')),verification_id TEXT REFERENCES verification_runs(id),created_at INTEGER NOT NULL);
CREATE TABLE learning_events(id TEXT PRIMARY KEY,event TEXT NOT NULL,details_json TEXT NOT NULL CHECK(json_valid(details_json)),created_at INTEGER NOT NULL);
CREATE INDEX learning_sessions_path ON practice_sessions(path_id,created_at);
CREATE INDEX learning_verification_session ON verification_runs(session_id,started_at);
CREATE INDEX learning_profiles_logical ON learning_profiles(logical_id,created_at);
INSERT INTO schema_migrations(version,name) VALUES(9,'learning_verification');
PRAGMA user_version=9;
